INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7296441, 1137894, 100831, '<td valign="top">cool!</td>', 'cool!', '2014-12-29 00:15:36.000000', NULL, 1),
(7296442, 1137962, 100831, '<td valign="top">excellent composition.</td>', 'excellent composition.', '2014-12-29 00:16:33.000000', NULL, 1),
(7296447, 1137875, 30982, '<td valign="top">Very sweet, and I like the way she''s framed within the painting.</td>', 'Very sweet, and I like the way she''s framed within the painting.', '2014-12-29 00:22:32.000000', NULL, 1),
(7296448, 1137983, 30982, '<td valign="top">The light here is wonderful, and I like the grain.  Sweet shot.</td>', 'The light here is wonderful, and I like the grain.  Sweet shot.', '2014-12-29 00:23:03.000000', NULL, 1),
(7296449, 1137872, 30982, '<td valign="top">I like the softness and tones of your processing.</td>', 'I like the softness and tones of your processing.', '2014-12-29 00:23:41.000000', NULL, 1),
(7296450, 1137861, 30982, '<td valign="top">I sometimes feel shooting people from behind is a bit of a cheat, but he does appear to have a bit of a stagger, and I like the gloves in the back pocket.</td>', 'I sometimes feel shooting people from behind is a bit of a cheat, but he does appear to have a bit of a stagger, and I like the gloves in the back pocket.', '2014-12-29 00:24:37.000000', NULL, 1),
(7296451, 1137757, 30982, '<td valign="top">Nice candid moment - seems there are a lot of entries with folks staring at screens, but then we all do a lot of that these days, don''t we?</td>', 'Nice candid moment - seems there are a lot of entries with folks staring at screens, but then we all do a lot of that these days, don''t we?', '2014-12-29 00:25:28.000000', NULL, 1),
(7296452, 1137870, 30982, '<td valign="top">There are some cloning artifacts that show up rather vividly on my screen - probably where you tried to tone down the really bright reflections?</td>', 'There are some cloning artifacts that show up rather vividly on my screen - probably where you tried to tone down the really bright reflections?', '2014-12-29 00:26:42.000000', NULL, 1),
(7296453, 1137663, 30982, '<td valign="top">One of the things that kinda bothers me (and it''s me, not you!) is the lack of a title, unless of course IMG_2116 is your title.  :-)  But this is such a great portrait that I will forgive you that oversight.  Just this once.  Really is an excellent portrait.</td>', 'One of the things that kinda bothers me (and it''s me, not you!) is the lack of a title, unless of course IMG_2116 is your title.  :-)  But this is such a great portrait that I will forgive you that oversight.  Just this once.  Really is an excellent portrait.', '2014-12-29 00:27:38.000000', NULL, 1),
(7296454, 1137973, 30982, '<td valign="top">She looks just a little overwhelmed with the celebrations!</td>', 'She looks just a little overwhelmed with the celebrations!', '2014-12-29 00:28:15.000000', NULL, 1),
(7296456, 1137906, 30982, '<td valign="top">I''m trying to figure out what those are - blankets, perhaps?  A nice environmental portrait.</td>', 'I''m trying to figure out what those are - blankets, perhaps?  A nice environmental portrait.', '2014-12-29 00:28:58.000000', NULL, 1),
(7296458, 1138006, 30982, '<td valign="top">She looks so terribly sad, even with her new friend.</td>', 'She looks so terribly sad, even with her new friend.', '2014-12-29 00:29:47.000000', NULL, 1),
(7296459, 1137952, 30982, '<td valign="top">Fun, cute shot!</td>', 'Fun, cute shot!', '2014-12-29 00:30:01.000000', NULL, 1),
(7296477, 1137890, 15511, '<td valign="top">It''s a captivating image. The selective saturation is unnecessary and a bit contrived. Still, well above average.</td>', 'It''s a captivating image. The selective saturation is unnecessary and a bit contrived. Still, well above average.', '2014-12-29 02:01:54.000000', NULL, 1),
(7296492, 1137951, 54446, '<td valign="top">This had potential.  For me, the sunglasses kill the image.   Eyes matter in portrait challenges.</td>', 'This had potential.  For me, the sunglasses kill the image.   Eyes matter in portrait challenges.', '2014-12-29 06:33:24.000000', NULL, 1),
(7296493, 1137870, 54446, '<td valign="top">Posterior shot.  No face visible.</td>', 'Posterior shot.  No face visible.', '2014-12-29 06:34:01.000000', NULL, 1),
(7296494, 1137861, 54446, '<td valign="top">Posterior shot.  No eyes.  Not a good choice for a portrait challenge.</td>', 'Posterior shot.  No eyes.  Not a good choice for a portrait challenge.', '2014-12-29 06:35:11.000000', NULL, 1),
(7296496, 1137917, 54446, '<td valign="top">I like this portrait.  An interesting man.</td>', 'I like this portrait.  An interesting man.', '2014-12-29 06:39:23.000000', NULL, 1),
(7296498, 1137953, 54446, '<td valign="top">dnmc</td>', 'dnmc', '2014-12-29 06:40:04.000000', NULL, 1),
(7296499, 1138004, 54446, '<td valign="top">Blue ribbon excellence.  10</td>', 'Blue ribbon excellence.  10', '2014-12-29 06:53:41.000000', NULL, 1),
(7296500, 1137663, 3735, '<td valign="top">[img][/img]</td>', '[img][/img]', '2014-12-29 06:54:31.000000', NULL, 1),
(7296501, 1138001, 54446, '<td valign="top">Very nicely done.  Excellent composition and seems quite candid.  Pro quality.  9</td>', 'Very nicely done.  Excellent composition and seems quite candid.  Pro quality.  9', '2014-12-29 06:55:03.000000', NULL, 1),
(7296502, 1138003, 54446, '<td valign="top">Excellent black and white.  Love her hands and eyes.  Superb challenge entry.  9</td>', 'Excellent black and white.  Love her hands and eyes.  Superb challenge entry.  9', '2014-12-29 06:55:54.000000', NULL, 1),
(7296503, 1137894, 54446, '<td valign="top">Well done!  A joy to view.</td>', 'Well done!  A joy to view.', '2014-12-29 06:57:28.000000', NULL, 1),
(7296504, 1137819, 54446, '<td valign="top">He''s watching the camera with his peripheral vision.  Okay, but a little "not candid enough".</td>', 'He''s watching the camera with his peripheral vision.  Okay, but a little "not candid enough".', '2014-12-29 07:00:04.000000', NULL, 1),
(7296506, 1137935, 54446, '<td valign="top">Excellent photograph.  Good use of light source.</td>', 'Excellent photograph.  Good use of light source.', '2014-12-29 07:00:47.000000', NULL, 1),
(7296507, 1137837, 54446, '<td valign="top">The texture added is a major distraction for me.  I know it has become "legal", but just because you can add elements does not mean you should.</td>', 'The texture added is a major distraction for me.  I know it has become "legal", but just because you can add elements does not mean you should.', '2014-12-29 07:01:02.000000', NULL, 1),
(7296508, 1137663, 54446, '<td valign="top">I didn''t mark down for this, but needs a title.</td>', 'I didn''t mark down for this, but needs a title.', '2014-12-29 07:01:26.000000', NULL, 1),
(7296509, 1137989, 54446, '<td valign="top">I''m confused as to why you would crop the image with the subject''s face on the border.  It is a portrait challenge.  This looks like a poor composition choice, or possibly a mistake.</td>', 'I''m confused as to why you would crop the image with the subject''s face on the border.  It is a portrait challenge.  This looks like a poor composition choice, or possibly a mistake.', '2014-12-29 07:02:12.000000', NULL, 1),
(7296510, 1137897, 54446, '<td valign="top">Beautiful girl.  I''m having some difficulty finding the candid nature of the shot.</td>', 'Beautiful girl.  I''m having some difficulty finding the candid nature of the shot.', '2014-12-29 07:03:18.000000', NULL, 1),
(7296511, 1137955, 54446, '<td valign="top">Charming portrait, but when she sees you taking the photo, it''s not candid.</td>', 'Charming portrait, but when she sees you taking the photo, it''s not candid.', '2014-12-29 07:04:47.000000', NULL, 1),
(7296512, 1137655, 54446, '<td valign="top">A subject without sunglasses would be more interesting.</td>', 'A subject without sunglasses would be more interesting.', '2014-12-29 07:05:42.000000', NULL, 1),
(7296513, 1138006, 54446, '<td valign="top">So, did you tell the fine lady to not look at the camera?</td>', 'So, did you tell the fine lady to not look at the camera?', '2014-12-29 07:07:09.000000', NULL, 1),
(7296553, 1137897, 118154, '<td valign="top">Not in my view very candid.</td>', 'Not in my view very candid.', '2014-12-29 10:43:28.000000', NULL, 1),
(7296554, 1137817, 118154, '<td valign="top">I think this is maybe the best here.</td>', 'I think this is maybe the best here.', '2014-12-29 10:46:46.000000', NULL, 1),
(7296556, 1137952, 118154, '<td valign="top">Something I really enjoy here, thanks.</td>', 'Something I really enjoy here, thanks.', '2014-12-29 10:48:55.000000', NULL, 1),
(7296566, 1137906, 163081, '<td valign="top">Excellent. A 9 from me</td>', 'Excellent. A 9 from me', '2014-12-29 11:47:40.000000', NULL, 1),
(7296567, 1137917, 163081, '<td valign="top">Just amazing picture. A 9 from me</td>', 'Just amazing picture. A 9 from me', '2014-12-29 11:48:51.000000', NULL, 1),
(7296580, 1138001, 163081, '<td valign="top">Excellent picture. Not exactly a portrait but I give it an 8.</td>', 'Excellent picture. Not exactly a portrait but I give it an 8.', '2014-12-29 12:01:24.000000', NULL, 1),
(7296656, 1137843, 107135, '<td valign="top">I like it</td>', 'I like it', '2014-12-29 14:42:41.000000', NULL, 1),
(7296670, 1137689, 54446, '<td valign="top">Exploitation of the homeless is not too cool.</td>', 'Exploitation of the homeless is not too cool.', '2014-12-29 15:52:27.000000', NULL, 1),
(7296755, 1137935, 30982, '<td valign="top">Really nice use of the light.</td>', 'Really nice use of the light.', '2014-12-29 22:17:50.000000', NULL, 1),
(7296756, 1137651, 30982, '<td valign="top">A nice swirl of pinks.  I''d guess she''s a dancer.</td>', 'A nice swirl of pinks.  I''d guess she''s a dancer.', '2014-12-29 22:18:10.000000', NULL, 1),
(7296757, 1137843, 30982, '<td valign="top">I was looking for something along these lines, too - the selfie is the new portrait, isn''t it?  Well done with this.</td>', 'I was looking for something along these lines, too - the selfie is the new portrait, isn''t it?  Well done with this.', '2014-12-29 22:18:43.000000', NULL, 1),
(7296758, 1137817, 30982, '<td valign="top">The gent in stripes looks less than amused.  It almost appears as though it''s a stage play in a way, though I realize it isn''t.  Then there''s the photographer in the mirror - another nice touch.  A very interesting photograph!</td>', 'The gent in stripes looks less than amused.  It almost appears as though it''s a stage play in a way, though I realize it isn''t.  Then there''s the photographer in the mirror - another nice touch.  A very interesting photograph!', '2014-12-29 22:19:30.000000', NULL, 1),
(7296759, 1137972, 30982, '<td valign="top">Such beautiful eyes, such a sad face.</td>', 'Such beautiful eyes, such a sad face.', '2014-12-29 22:19:51.000000', NULL, 1),
(7296760, 1137819, 30982, '<td valign="top">I  often wonder why people shoot portraits with hands on chins, until I realized one day people do sit that way from time to time.</td>', 'I  often wonder why people shoot portraits with hands on chins, until I realized one day people do sit that way from time to time.', '2014-12-29 22:20:19.000000', NULL, 1),
(7296761, 1137921, 30982, '<td valign="top">So very joyous!  The solid back background is a bit offputting to me - she looks almost as though she''s floating in space.</td>', 'So very joyous!  The solid back background is a bit offputting to me - she looks almost as though she''s floating in space.', '2014-12-29 22:21:56.000000', NULL, 1),
(7296762, 1138012, 30982, '<td valign="top">Almost looks as though it could also work as a painting, like the challenge we just had.  Very peaceful.</td>', 'Almost looks as though it could also work as a painting, like the challenge we just had.  Very peaceful.', '2014-12-29 22:22:36.000000', NULL, 1),
(7296763, 1137950, 30982, '<td valign="top">They do seem intent.  Too bad about the closed eyes, though it''s hard to get everyone all at once sometimes!</td>', 'They do seem intent.  Too bad about the closed eyes, though it''s hard to get everyone all at once sometimes!', '2014-12-29 22:23:12.000000', NULL, 1),
(7296764, 1137975, 30982, '<td valign="top">That''s one about to be unhappy baby!  An interesting shot - it''s almost a bit spooky, with the just one eye in focus, but I think it''s a good photo.</td>', 'That''s one about to be unhappy baby!  An interesting shot - it''s almost a bit spooky, with the just one eye in focus, but I think it''s a good photo.', '2014-12-29 22:24:09.000000', NULL, 1),
(7296766, 1137770, 30982, '<td valign="top">So very much the shot of the day these days, isn''t it?  Beautiful work with the natural light.</td>', 'So very much the shot of the day these days, isn''t it?  Beautiful work with the natural light.', '2014-12-29 22:24:28.000000', NULL, 1),
(7296767, 1137890, 30982, '<td valign="top">I''m not a huge fan of selective desaturation, but it kinda works in a way here.  I''d like to see this in full color to see how much the story changes when presented that way.</td>', 'I''m not a huge fan of selective desaturation, but it kinda works in a way here.  I''d like to see this in full color to see how much the story changes when presented that way.', '2014-12-29 22:25:18.000000', NULL, 1),
(7296768, 1137951, 30982, '<td valign="top">He seems both intent and content.  A nice catch.</td>', 'He seems both intent and content.  A nice catch.', '2014-12-29 22:26:03.000000', NULL, 1),
(7296769, 1137862, 30982, '<td valign="top">An excellent candid - to me, exactly what a candid should be.  You''ve caught a nice moment in time, and a good smile, without anything fake or contrived - at least as presented here.</td>', 'An excellent candid - to me, exactly what a candid should be.  You''ve caught a nice moment in time, and a good smile, without anything fake or contrived - at least as presented here.', '2014-12-29 22:26:46.000000', NULL, 1),
(7296770, 1137714, 30982, '<td valign="top">Great evening light - matches their hair!</td>', 'Great evening light - matches their hair!', '2014-12-29 22:27:01.000000', NULL, 1),
(7296771, 1137985, 30982, '<td valign="top">Heh!  A very fun moment.</td>', 'Heh!  A very fun moment.', '2014-12-29 22:27:33.000000', NULL, 1),
(7296772, 1137940, 30982, '<td valign="top">Heh!  No one actually talks to one another any more, do they?  They just read messages on their phones, even when they''re with other people.  I like that you left this in color.</td>', 'Heh!  No one actually talks to one another any more, do they?  They just read messages on their phones, even when they''re with other people.  I like that you left this in color.', '2014-12-29 22:28:06.000000', NULL, 1),
(7296796, 1137840, 30982, '<td valign="top">It''s that after dinner food coma.... nice use of the light.  I''m sure your subject is gonna kill you for entering this...</td>', 'It''s that after dinner food coma.... nice use of the light.  I''m sure your subject is gonna kill you for entering this...', '2014-12-29 23:56:21.000000', NULL, 1),
(7296797, 1137955, 30982, '<td valign="top">Sweet catch!  Love the lashes on the little one.</td>', 'Sweet catch!  Love the lashes on the little one.', '2014-12-29 23:56:43.000000', NULL, 1),
(7296798, 1137963, 30982, '<td valign="top">I like the genuine smile here - they look like they''re having fun!</td>', 'I like the genuine smile here - they look like they''re having fun!', '2014-12-29 23:57:06.000000', NULL, 1),
(7296800, 1137868, 30982, '<td valign="top">A different version of pin the tail on the donkey, perhaps?</td>', 'A different version of pin the tail on the donkey, perhaps?', '2014-12-29 23:57:47.000000', NULL, 1),
(7296801, 1137931, 30982, '<td valign="top">A very good environmental portrait.  I do like the balance of this.</td>', 'A very good environmental portrait.  I do like the balance of this.', '2014-12-29 23:59:01.000000', NULL, 1),
(7296802, 1137849, 30982, '<td valign="top">Is that Freddie Mercury on his shirt?  A quick but interesting grab!</td>', 'Is that Freddie Mercury on his shirt?  A quick but interesting grab!', '2014-12-29 23:59:37.000000', NULL, 1),
(7296803, 1138004, 30982, '<td valign="top">Lovely attention to detail.</td>', 'Lovely attention to detail.', '2014-12-30 00:00:26.000000', NULL, 1),
(7296804, 1137917, 30982, '<td valign="top">Excellent candid.  I especially like the bokeh off the water, and what a great face!</td>', 'Excellent candid.  I especially like the bokeh off the water, and what a great face!', '2014-12-30 00:00:51.000000', NULL, 1),
(7296805, 1137655, 30982, '<td valign="top">Love the hair!  Great catch, and really nice processing to suit the image.</td>', 'Love the hair!  Great catch, and really nice processing to suit the image.', '2014-12-30 00:04:02.000000', NULL, 1),
(7296806, 1137967, 30982, '<td valign="top">Awww - sweet!  I hope they got what they wanted.  And I hope they''re good at sharing!</td>', 'Awww - sweet!  I hope they got what they wanted.  And I hope they''re good at sharing!', '2014-12-30 00:04:29.000000', NULL, 1),
(7296807, 1137924, 30982, '<td valign="top">Looks like quite the undertaking!  I like the contrast is how warmly everyone is dresssed, from a short sleeved shirt to full down jackets and scarves.</td>', 'Looks like quite the undertaking!  I like the contrast is how warmly everyone is dresssed, from a short sleeved shirt to full down jackets and scarves.', '2014-12-30 00:05:38.000000', NULL, 1),
(7296808, 1137852, 30982, '<td valign="top">A good casual portrait but a bit overprocessed for my taste.</td>', 'A good casual portrait but a bit overprocessed for my taste.', '2014-12-30 00:07:24.000000', NULL, 1),
(7296809, 1137930, 30982, '<td valign="top">Not sure if they''re about to cry or laugh!</td>', 'Not sure if they''re about to cry or laugh!', '2014-12-30 00:07:48.000000', NULL, 1),
(7296810, 1137929, 30982, '<td valign="top">Pinhole!  Sensor dust!  He''s got a giant bird on his head!  Definitely a unique take on the challenge.  Quite fun!</td>', 'Pinhole!  Sensor dust!  He''s got a giant bird on his head!  Definitely a unique take on the challenge.  Quite fun!', '2014-12-30 00:08:29.000000', NULL, 1),
(7296811, 1137892, 30982, '<td valign="top">Good catch!  I like the look between father and daughter - kind of that knowing "he''ll need a little help here" sorta thing.</td>', 'Good catch!  I like the look between father and daughter - kind of that knowing "he''ll need a little help here" sorta thing.', '2014-12-30 00:09:40.000000', NULL, 1),
(7296812, 1137961, 30982, '<td valign="top">Quiet, peaceful slice of life.  Pun somewhat intended.</td>', 'Quiet, peaceful slice of life.  Pun somewhat intended.', '2014-12-30 00:09:59.000000', NULL, 1),
(7296813, 1137883, 30982, '<td valign="top">I sense they''re bored, and at some resort town in a less than desirable hotel, wishing they''d picked a better place.</td>', 'I sense they''re bored, and at some resort town in a less than desirable hotel, wishing they''d picked a better place.', '2014-12-30 00:10:34.000000', NULL, 1),
(7296814, 1138003, 30982, '<td valign="top">The no-look shot - yet your seat mate knows what you''re up to, though.  If she''s homeless, someone is doing a good job of helping her out - that''s a nice coat and a very nice bag.  Excellent candid.</td>', 'The no-look shot - yet your seat mate knows what you''re up to, though.  If she''s homeless, someone is doing a good job of helping her out - that''s a nice coat and a very nice bag.  Excellent candid.', '2014-12-30 00:11:48.000000', NULL, 1),
(7296815, 1137953, 30982, '<td valign="top">Since we''re looking for people, I''m not sure where to find one here.  That said, I love the placemat!  Not as fond of the texture overriding the cat but I like how it works on the floor.</td>', 'Since we''re looking for people, I''m not sure where to find one here.  That said, I love the placemat!  Not as fond of the texture overriding the cat but I like how it works on the floor.', '2014-12-30 00:13:11.000000', NULL, 1),
(7296816, 1137894, 30982, '<td valign="top">Awesome found collage.  Those eyes are eerie!</td>', 'Awesome found collage.  Those eyes are eerie!', '2014-12-30 00:13:50.000000', NULL, 1),
(7296817, 1137989, 30982, '<td valign="top">Best title of the challenge.</td>', 'Best title of the challenge.', '2014-12-30 00:14:05.000000', NULL, 1),
(7296818, 1138001, 30982, '<td valign="top">I love her concentration.  And she has tiny feet!</td>', 'I love her concentration.  And she has tiny feet!', '2014-12-30 00:14:25.000000', NULL, 1),
(7296820, 1137689, 30982, '<td valign="top">Meets the challenge well!  Not my style of processing - I prefer it a bit more realistic, I guess, but that''s my personal preference.</td>', 'Meets the challenge well!  Not my style of processing - I prefer it a bit more realistic, I guess, but that''s my personal preference.', '2014-12-30 00:16:00.000000', NULL, 1),
(7296822, 1137968, 30982, '<td valign="top">She''s contemplating that biscuit quite seriously.  I wonder how this looks in color, as it seems a bit bleak to me in B&amp;W (and I''m normally a B&amp;W kinda gal.)  I just wonder if it would suit her personality/spirit better, but I don''t know her so really can''t say.</td>', 'She''s contemplating that biscuit quite seriously.  I wonder how this looks in color, as it seems a bit bleak to me in B&W (and I''m normally a B&W kinda gal.)  I just wonder if it would suit her personality/spirit better, but I don''t know her so really can''t say.', '2014-12-30 00:19:11.000000', NULL, 1),
(7296823, 1137837, 30982, '<td valign="top">Somehow this seems quite appropriate for the challenge.  Not a "candid portrait" per se (we go back to my "it''s sorta cheating to shoot the backs of people" thing) but to "Capture a portrait of a person (or people) in their natural element without their knowledge" - well that''s what you''ve got here!  Did you shoot through a window or add texture or both?</td>', 'Somehow this seems quite appropriate for the challenge.  Not a "candid portrait" per se (we go back to my "it''s sorta cheating to shoot the backs of people" thing) but to "Capture a portrait of a person (or people) in their natural element without their knowledge" - well that''s what you''ve got here!  Did you shoot through a window or add texture or both?', '2014-12-30 00:20:51.000000', NULL, 1),
(7296824, 1138011, 30982, '<td valign="top">I wish we could see just a bit more of the real eye lashes - they get a little lost in the background.  I like the reflected eye.</td>', 'I wish we could see just a bit more of the real eye lashes - they get a little lost in the background.  I like the reflected eye.', '2014-12-30 00:22:45.000000', NULL, 1),
(7296825, 1137897, 30982, '<td valign="top">A great smile!  A candid portrait by a standard definition - perhaps not as much by this challenge definition but I realize not everyone reads the full definition.</td>', 'A great smile!  A candid portrait by a standard definition - perhaps not as much by this challenge definition but I realize not everyone reads the full definition.', '2014-12-30 00:23:51.000000', NULL, 1),
(7296827, 1137911, 30982, '<td valign="top">Cute little tyke with a great smile.</td>', 'Cute little tyke with a great smile.', '2014-12-30 00:25:14.000000', NULL, 1),
(7296838, 1137962, 114285, '<td valign="top">Loving his smile, and interaction...best on here by a mile, all the best!!</td>', 'Loving his smile, and interaction...best on here by a mile, all the best!!', '2014-12-30 08:44:26.000000', NULL, 1),
(7296839, 1138004, 114285, '<td valign="top">Cute and adorable, I get the feeling maybe a little too set up as we all know whose this is, and her lovely clothing implies this was not a random image. But I''m judging the quality of the photo which is flawless.</td>', 'Cute and adorable, I get the feeling maybe a little too set up as we all know whose this is, and her lovely clothing implies this was not a random image. But I''m judging the quality of the photo which is flawless.', '2014-12-30 08:48:18.000000', NULL, 1),
(7296857, 1137663, 16046, '<td valign="top">Best in show award, congrats, but could not score it a 10 because no title</td>', 'Best in show award, congrats, but could not score it a 10 because no title', '2014-12-30 11:22:54.000000', NULL, 1),
(7296858, 1137983, 16046, '<td valign="top">Top 3</td>', 'Top 3', '2014-12-30 11:23:15.000000', NULL, 1),
(7296859, 1137852, 16046, '<td valign="top">Top 3</td>', 'Top 3', '2014-12-30 11:23:30.000000', NULL, 1),
(7296860, 1137663, 19825, '<td valign="top">This is awesome. I can feel the weight of the world has settled on him. Nicely composed with wonderful light. It is not a problem with me, but I am not sure the title IMG_2116 is doing it justice. If you sent a message to SC I think they can change the title while it''s still in voting. I''d do it -- right or wrong, a decent title will help your score. Fantastic shot.</td>', 'This is awesome. I can feel the weight of the world has settled on him. Nicely composed with wonderful light. It is not a problem with me, but I am not sure the title IMG_2116 is doing it justice. If you sent a message to SC I think they can change the title while it''s still in voting. I''d do it -- right or wrong, a decent title will help your score. Fantastic shot.', '2014-12-30 11:25:40.000000', NULL, 1),
(7296864, 1137651, 19825, '<td valign="top">A fleeting moment captured. Nicely done.</td>', 'A fleeting moment captured. Nicely done.', '2014-12-30 11:39:20.000000', NULL, 1),
