(7298154, 1137972, 173844, '<td valign="top">Knowing she''s in a hospital waiting room adds resonance to an already resonant portrait.</td>', 'Knowing she''s in a hospital waiting room adds resonance to an already resonant portrait.', '2015-01-03 11:46:18.000000', NULL, 1),
(7298155, 1137875, 173844, '<td valign="top">Her happy face is so well-paired with the colorful painting in the near background.  The gold upper border is an over-all source of sunlight.  Is that a giant flamingo feeding behind her right cheek?  Lovely portrait.</td>', 'Her happy face is so well-paired with the colorful painting in the near background.  The gold upper border is an over-all source of sunlight.  Is that a giant flamingo feeding behind her right cheek?  Lovely portrait.', '2015-01-03 12:01:54.000000', NULL, 1),
(7298164, 1137890, 173844, '<td valign="top">Against my stereotypical esthetic (please pardon the pretentiousness), I like this partial desaturation very much.  Lot of emotion in that figure.  The sumptuous foreground foliage charges the atmosphere.</td>', 'Against my stereotypical esthetic (please pardon the pretentiousness), I like this partial desaturation very much.  Lot of emotion in that figure.  The sumptuous foreground foliage charges the atmosphere.', '2015-01-03 12:35:25.000000', NULL, 1),
