(7298208, 1137961, 37858, '<td valign="top">I like this image because of the lighting and shadows, the intense concentration evident in his face, the obvious "candid" nature of the photograph, and the framing with the dark curtain on the left balanced by the dark item on the wall behind him (chalkboard?).</td>', 'I like this image because of the lighting and shadows, the intense concentration evident in his face, the obvious "candid" nature of the photograph, and the framing with the dark curtain on the left balanced by the dark item on the wall behind him (chalkboard?).', '2015-01-03 13:43:47.000000', NULL, 1),
(7298213, 1137655, 37858, '<td valign="top">Nicely done.  I like how she pretty much fills the center of the image and that she is flanked by dark tones of others in the background.  Good use of vignette, too.</td>', 'Nicely done.  I like how she pretty much fills the center of the image and that she is flanked by dark tones of others in the background.  Good use of vignette, too.', '2015-01-03 13:45:57.000000', NULL, 1),
