(7298631, 1138003, 104230, '<td valign="top">Great capture and processing. Interesting reflection of you and the woman sitting next to you who is obviously interested in what you''re doing/capturing</td>', 'Great capture and processing. Interesting reflection of you and the woman sitting next to you who is obviously interested in what you''re doing/capturing', '2015-01-04 14:56:50.000000', NULL, 1),
(7298632, 1137870, 104230, '<td valign="top">I feel as if I''m leaning to the right by about 10-15 degrees which is disorienting (I guess literally in this case!).  Would have been nice to have captured some of her face, not just a back view.</td>', 'I feel as if I''m leaning to the right by about 10-15 degrees which is disorienting (I guess literally in this case!).  Would have been nice to have captured some of her face, not just a back view.', '2015-01-04 15:01:56.000000', NULL, 1),
(7298633, 1137872, 104230, '<td valign="top">I''m not a fan of the processing here. It flattens the light/image so much.</td>', 'I''m not a fan of the processing here. It flattens the light/image so much.', '2015-01-04 15:04:03.000000', NULL, 1),
(7298634, 1137843, 104230, '<td valign="top">A very contemporary image... The lady on the right eating something is looking very suspicious.  Great capture.</td>', 'A very contemporary image... The lady on the right eating something is looking very suspicious.  Great capture.', '2015-01-04 15:06:21.000000', NULL, 1),
