(7298806, 1137968, 13077, '<td valign="top">Excellent. Somehow harsh but flattering at the same time; her lines and wrinkles were earned and are displayed as badges here.</td>', 'Excellent. Somehow harsh but flattering at the same time; her lines and wrinkles were earned and are displayed as badges here.', '2015-01-04 23:33:04.000000', NULL, 1),
(7298807, 1137819, 13077, '<td valign="top">Would probably have been improved by cropping tighter to get rid of the brighter white line at the left, and if it was shot in RAW trying to rein in the highlights a bit.</td>', 'Would probably have been improved by cropping tighter to get rid of the brighter white line at the left, and if it was shot in RAW trying to rein in the highlights a bit.', '2015-01-04 23:34:07.000000', NULL, 1),
(7298808, 1137840, 13077, '<td valign="top">Visually very strong, the shapes and light work well, and the man looks very comfortable napping there. He might not consider it a flattering photo, but he looks very content and in his element.</td>', 'Visually very strong, the shapes and light work well, and the man looks very comfortable napping there. He might not consider it a flattering photo, but he looks very content and in his element.', '2015-01-04 23:35:09.000000', NULL, 1),
(7298810, 1137817, 13077, '<td valign="top">Very interesting. Did you catch your own reflection or is that someone else taking a photo at the same time?<br/>I like the moment you''ve caught either way.</td>', 'Very interesting. Did you catch your own reflection or is that someone else taking a photo at the same time?I like the moment you''ve caught either way.', '2015-01-04 23:37:31.000000', NULL, 1),
(7298811, 1137655, 13077, '<td valign="top">Excellent. Good soft light, impeccable timing and composition with the out-of-focus ladies in the background and the buildings.</td>', 'Excellent. Good soft light, impeccable timing and composition with the out-of-focus ladies in the background and the buildings.', '2015-01-04 23:38:13.000000', NULL, 1),
